// features/lifecycle.feature: A certificate that expires today can still be approved
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

import { expect, expectStatus, sample, test } from "../../fixtures";

test("a certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ apiAs, factory }, testInfo) => {
  // Arrange
  // The server compares expiry against its UTC date (utcnow().date()).
  const today = new Date().toISOString().slice(0, 10);
  const certificate = readFileSync(sample("insurance_certificate.txt"), "utf-8").replace(
    /^Expiry Date: .*$/m,
    `Expiry Date: ${today}`,
  );
  expect(certificate, "sample certificate carries today's expiry").toContain(`Expiry Date: ${today}`);
  const certificatePath = testInfo.outputPath("insurance_certificate_expires_today.txt");
  writeFileSync(certificatePath, certificate);
  const { extractions } = await factory.vendorInReview({
    files: { insurance_certificate: path.relative(sample("."), certificatePath) },
  });
  const reviewer = await apiAs("reviewer");

  // Act
  const response = await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const decided = await expectStatus(response, 200);
  expect(decided.status).toBe("approved");
  const stored = await factory.extraction(decided.document_id, "reviewer");
  expect(stored.status).toBe("approved");
});
